#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    int n;
    if (!(cin >> n)) return 0;
    vector<long long> h(n);
    for (int i = 0; i < n; i++) cin >> h[i];

    long long left = 0, right = n - 1;
    long long maxWater = 0;

    while (left < right) {
        long long width = right - left;
        long long height = min(h[left], h[right]);
        maxWater = max(maxWater, width * height);

        if (h[left] < h[right]) {
            left++;
        } else {
            right--;
        }
    }

    cout << maxWater << endl;
    return 0;
}

